import{d as v}from"./chunks/tutorials.data.DzkZxi-8.js";import{_ as u,v as h,C as g,o as s,c as r,a8 as n,j as a,a as t,e as l,E as m,k as b,p as c}from"./chunks/framework.DBq9MM9W.js";const f={key:0},k={key:1},w=JSON.parse('{"title":"Titiler Integration","description":"","frontmatter":{"title":"Titiler Integration","layout":"page","llm":[{"heading":"Integration Examples","source":"../../content/tutorials.data.js","items":"titiler","title":"title","link":{"field":"link"},"fields":["content","features"]}]},"headers":[{"level":2,"title":"Titiler Integration","slug":"titiler-integration","link":"#titiler-integration","children":[{"level":3,"title":"Overview","slug":"overview","link":"#overview","children":[]},{"level":3,"title":"Quick Start","slug":"quick-start","link":"#quick-start","children":[]},{"level":3,"title":"API Documentation","slug":"api-documentation","link":"#api-documentation","children":[]},{"level":3,"title":"Key Concepts","slug":"key-concepts","link":"#key-concepts","children":[]},{"level":3,"title":"Deployment Options","slug":"deployment-options","link":"#deployment-options","children":[]},{"level":3,"title":"Next Steps","slug":"next-steps","link":"#next-steps","children":[]}]}],"relativePath":"software-services/titiler/index.md","filePath":"software-services/titiler/index.md"}'),x={name:"software-services/titiler/index.md"},y=Object.assign(x,{setup(_){const i=c(!1),o=c(!0);return h(async()=>{try{const d=await fetch("https://api.explorer.eopf.copernicus.eu/raster/_mgmt/ping");i.value=d.ok}catch{i.value=!1}finally{o.value=!1}}),(d,e)=>{const p=g("FeaturesGallery");return s(),r("div",null,[e[2]||(e[2]=n('<h2 id="titiler-integration" tabindex="-1" data-v-6e90d0a7>Titiler Integration <img src="https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png" alt="Titiler Logo" style="height:100px;vertical-align:middle;margin-left:0.5rem;float:right;" data-v-6e90d0a7> <a class="header-anchor link" href="#titiler-integration" aria-label="Permalink to &quot;Titiler Integration &lt;img src=&quot;https://user-images.githubusercontent.com/10407788/172718020-c2378b7e-a0d4-406e-924c-8ffe54e61596.png&quot; alt=&quot;Titiler Logo&quot; style=&quot;height:100px;vertical-align:middle;margin-left:0.5rem;float:right;&quot; /&gt;&quot;" data-v-6e90d0a7>​</a></h2><h3 id="overview" tabindex="-1" data-v-6e90d0a7>Overview <a class="header-anchor link" href="#overview" aria-label="Permalink to &quot;Overview&quot;" data-v-6e90d0a7>​</a></h3><p data-v-6e90d0a7>This guide demonstrates how to use Titiler-EOPF, a specialized tile server that provides on-the-fly visualization of EOPF&#39;s Zarr-formatted satellite data. Unlike client-side processing, Titiler handles complex calculations server-side and delivers optimized tiles for web mapping applications.</p>',3)),o.value?(s(),r("div",f,[...e[0]||(e[0]=[a("div",{class:"tip custom-block"},[a("p",{class:"custom-block-title"},[t("💡 "),a("strong",null,[t("Checking "),a("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link vp-external-link-icon",target:"_blank",rel:"noreferrer"},"API"),t(" Status")]),t(":Verifying Titiler service availability...")])],-1)])])):l("",!0),i.value?l("",!0):(s(),r("div",k,[...e[1]||(e[1]=[a("div",{class:"warning custom-block"},[a("p",{class:"custom-block-title"},[t("⚠️ "),a("strong",null,[a("a",{href:"https://api.explorer.eopf.copernicus.eu/raster",class:"link vp-external-link-icon",target:"_blank",rel:"noreferrer"},"API"),t(" Unavailable")]),t(":: The Titiler service appears to be temporarily unavailable. Some examples may not work as expected.")])],-1)])])),e[3]||(e[3]=n('<br data-v-6e90d0a7><div class="info custom-block" data-v-6e90d0a7><p class="custom-block-title" data-v-6e90d0a7><strong data-v-6e90d0a7><i class="mdi mdi-target" data-v-6e90d0a7></i> What You&#39;ll Learn</strong></p><p data-v-6e90d0a7>This integration guide covers server-side tile generation using EOPF&#39;s Titiler service, enabling you to build responsive web applications without handling complex data processing in the browser. Each example demonstrates practical implementation patterns for real-world applications.</p><p data-v-6e90d0a7><strong data-v-6e90d0a7>Sample Data</strong> used here are available in <a href="https://api.explorer.eopf.copernicus.eu/browser/external/api.explorer.eopf.copernicus.eu/stac/collections/sentinel-2-l2a" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>the Sentinel-2 L2A collection in STAC Browser</a></p></div><h3 id="quick-start" tabindex="-1" data-v-6e90d0a7>Quick Start <a class="header-anchor link" href="#quick-start" aria-label="Permalink to &quot;Quick Start&quot;" data-v-6e90d0a7>​</a></h3><br data-v-6e90d0a7><div class="info custom-block" data-v-6e90d0a7><p class="custom-block-title" data-v-6e90d0a7><strong data-v-6e90d0a7><i class="mdi mdi-rocket-launch" data-v-6e90d0a7></i> Get Started in 5 Minutes</strong></p><p data-v-6e90d0a7>Ready to dive in? Start with the <a href="./rgb" class="link" data-v-6e90d0a7>RGB Visualization example</a> to see Titiler serving EOPF tiles in a web map, then explore NDVI calculations and spatial cropping techniques</p></div><br data-v-6e90d0a7><div class="warning custom-block" data-v-6e90d0a7><p class="custom-block-title" data-v-6e90d0a7>⚠️ <strong data-v-6e90d0a7>Early Implementation</strong></p><p data-v-6e90d0a7>This Titiler integration represents an early implementation of EOPF data services. Data availability, API stability, and library alignment will evolve over time as the platform matures.</p></div><h3 id="api-documentation" tabindex="-1" data-v-6e90d0a7>API Documentation <a class="header-anchor link" href="#api-documentation" aria-label="Permalink to &quot;API Documentation&quot;" data-v-6e90d0a7>​</a></h3><div class="grid" data-v-6e90d0a7><div class="s12 m6" data-v-6e90d0a7><div class="info custom-block" data-v-6e90d0a7><p class="custom-block-title" data-v-6e90d0a7>Interactive API Docs</p><p data-v-6e90d0a7><a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>Swagger UI Documentation</a></p><p data-v-6e90d0a7>Complete API reference with interactive examples and endpoint testing.</p></div></div><div class="s12 m6" data-v-6e90d0a7><div class="info custom-block" data-v-6e90d0a7><p class="custom-block-title" data-v-6e90d0a7>Base URL</p><p data-v-6e90d0a7><a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>https://api.explorer.eopf.copernicus.eu/raster/</a></p><p data-v-6e90d0a7>All tile endpoints use this base URL for production integration.</p><br data-v-6e90d0a7></div></div></div><h3 id="key-concepts" tabindex="-1" data-v-6e90d0a7>Key Concepts <a class="header-anchor link" href="#key-concepts" aria-label="Permalink to &quot;Key Concepts&quot;" data-v-6e90d0a7>​</a></h3><p data-v-6e90d0a7><strong data-v-6e90d0a7>Server-Side Processing</strong></p><p data-v-6e90d0a7>Titiler-EOPF performs all data processing server-side, including:</p><ul data-v-6e90d0a7><li data-v-6e90d0a7><strong data-v-6e90d0a7>On-the-fly tile generation</strong> from Zarr datasets</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Mathematical expressions</strong> for band combinations and indices</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Color enhancement</strong> with gamma correction and contrast adjustment</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Spatial operations</strong> like cropping and reprojection</li></ul><p data-v-6e90d0a7><strong data-v-6e90d0a7>Asset and Band Selection</strong></p><p data-v-6e90d0a7>Titiler resolves each item through the STAC API and reads bands from its assets. Band selection uses the format:</p><div class="language- vp-adaptive-theme" data-v-6e90d0a7><button title="Copy Code" class="copy" data-v-6e90d0a7></button><span class="lang" data-v-6e90d0a7></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-6e90d0a7><code data-v-6e90d0a7><span class="line" data-v-6e90d0a7><span data-v-6e90d0a7>assets=reflectance|bands=b04,b03,b02</span></span></code></pre></div><ul data-v-6e90d0a7><li data-v-6e90d0a7><code data-v-6e90d0a7>reflectance</code> - STAC asset of the item (for Sentinel-2 L2A, the asset that holds the spectral bands)</li><li data-v-6e90d0a7><code data-v-6e90d0a7>bands=b04,b03,b02</code> - Bands to read from that asset, by band name (<code data-v-6e90d0a7>b04</code>) or by the common name the asset assigns to the band (<code data-v-6e90d0a7>red</code>)</li></ul><p data-v-6e90d0a7>To compute a band operation instead, pass an <code data-v-6e90d0a7>expression</code> in place of <code data-v-6e90d0a7>bands</code>. It references the asset&#39;s bands by name, for example NDVI from NIR (<code data-v-6e90d0a7>b08</code>) and red (<code data-v-6e90d0a7>b04</code>):</p><div class="language- vp-adaptive-theme" data-v-6e90d0a7><button title="Copy Code" class="copy" data-v-6e90d0a7></button><span class="lang" data-v-6e90d0a7></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-6e90d0a7><code data-v-6e90d0a7><span class="line" data-v-6e90d0a7><span data-v-6e90d0a7>assets=reflectance|expression=(b08-b04)/(b08+b04)</span></span></code></pre></div><p data-v-6e90d0a7>URL-encode the <code data-v-6e90d0a7>assets</code> value when building the URL by hand; an unencoded <code data-v-6e90d0a7>+</code> is read as a space and the request fails. <code data-v-6e90d0a7>URLSearchParams</code> and <code data-v-6e90d0a7>encodeURIComponent</code> handle this.</p><p data-v-6e90d0a7><strong data-v-6e90d0a7>URL Structure</strong></p><p data-v-6e90d0a7>Titiler exposes three route levels:</p><table tabindex="0" data-v-6e90d0a7><thead data-v-6e90d0a7><tr data-v-6e90d0a7><th data-v-6e90d0a7>Route</th><th data-v-6e90d0a7>Scope</th></tr></thead><tbody data-v-6e90d0a7><tr data-v-6e90d0a7><td data-v-6e90d0a7><code data-v-6e90d0a7>/raster/collections/{collection}</code></td><td data-v-6e90d0a7>Mosaic of all items in a collection</td></tr><tr data-v-6e90d0a7><td data-v-6e90d0a7><code data-v-6e90d0a7>/raster/collections/{collection}/items/{item}</code></td><td data-v-6e90d0a7>One item; can combine bands from several assets</td></tr><tr data-v-6e90d0a7><td data-v-6e90d0a7><code data-v-6e90d0a7>/raster/collections/{collection}/items/{item}/assets/{asset}</code></td><td data-v-6e90d0a7>One asset of one item</td></tr></tbody></table><p data-v-6e90d0a7>The examples in this guide use the item route. Tile endpoints follow this pattern:</p><div class="language- vp-adaptive-theme" data-v-6e90d0a7><button title="Copy Code" class="copy" data-v-6e90d0a7></button><span class="lang" data-v-6e90d0a7></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0" data-v-6e90d0a7><code data-v-6e90d0a7><span class="line" data-v-6e90d0a7><span data-v-6e90d0a7>/raster/collections/{collection}/items/{item}/tiles/WebMercatorQuad/{z}/{x}/{y}.png</span></span></code></pre></div><h3 id="deployment-options" tabindex="-1" data-v-6e90d0a7>Deployment Options <a class="header-anchor link" href="#deployment-options" aria-label="Permalink to &quot;Deployment Options&quot;" data-v-6e90d0a7>​</a></h3><p data-v-6e90d0a7><strong data-v-6e90d0a7>1. <a href="https://api.explorer.eopf.copernicus.eu/raster/" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>EOPF Explorer TiTiler</a> (Recommended)</strong></p><ul data-v-6e90d0a7><li data-v-6e90d0a7><strong data-v-6e90d0a7>Pre-configured</strong> with STAC catalog integration</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Production-ready</strong> endpoints with optimized performance</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>No authentication</strong> required for public data</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Automatic updates</strong> with latest EOPF data</li></ul><p data-v-6e90d0a7><strong data-v-6e90d0a7>2. Self-Hosted Instance</strong></p><p data-v-6e90d0a7>For custom deployments, see the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>titiler-eopf repository</a> for:</p><ul data-v-6e90d0a7><li data-v-6e90d0a7>Docker Compose setup instructions</li><li data-v-6e90d0a7>Kubernetes/Helm deployment guides</li><li data-v-6e90d0a7>Environment configuration examples</li><li data-v-6e90d0a7>Custom data source integration</li></ul><h3 id="next-steps" tabindex="-1" data-v-6e90d0a7>Next Steps <a class="header-anchor link" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;" data-v-6e90d0a7>​</a></h3><ol data-v-6e90d0a7><li data-v-6e90d0a7><strong data-v-6e90d0a7>Start with Examples</strong>: Work through each <a href="#integration-examples" class="link" data-v-6e90d0a7>example</a> to understand the capabilities</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Explore API Documentation</strong>: Use the <a href="https://api.explorer.eopf.copernicus.eu/raster/api.html" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>interactive Swagger UI</a> to test endpoints</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Browse EOPF Data</strong>: Find datasets in the <a href="https://api.explorer.eopf.copernicus.eu/browser" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>STAC Browser</a></li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Build Applications</strong>: Integrate Titiler tiles into your web mapping projects</li><li data-v-6e90d0a7><strong data-v-6e90d0a7>Community</strong>: Join <a href="https://discourse.eopf.copernicus.eu/c/eopf-explorer/17" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>discussions</a> and contribute to the growing EOPF ecosystem</li></ol><p data-v-6e90d0a7>For the latest updates and advanced features, follow the <a href="https://github.com/EOPF-Explorer/titiler-eopf" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>Titiler-EOPF project</a> and <a href="https://github.com/EOPF-Explorer" class="link vp-external-link-icon" target="_blank" rel="noreferrer" data-v-6e90d0a7>EOPF Explorer platform</a> on GitHub.</p>',34)),m(p,{id:"integration-examples",background:"transparent",sectionTitle:"Integration Examples",cards:b(v).titiler},null,8,["cards"])])}}}),S=u(y,[["__scopeId","data-v-6e90d0a7"]]);export{w as __pageData,S as default};
